Privileges systeme : CREATE SESSION, CREATE TABLE, CREATE VIEW...
GRANT privilege TO utilisateur;
REVOKE privilege FROM utilisateur;
Roles predifinis : CONNECT, RESOURCE, DBA
CREATE ROLE nom; GRANT privileges TO nom_role;
GRANT nom_role TO utilisateur;
WITH GRANT OPTION : permet de transmettre le privilege.

CREATE TABLE nom (col1 TYPE CONSTRAINT, col2 TYPE...);
Types : NUMBER, VARCHAR2(n), DATE, CHAR(n)
Contraintes : PRIMARY KEY, FOREIGN KEY REFERENCES, NOT NULL, UNIQUE, CHECK
INSERT INTO table VALUES (...);
SELECT col FROM table WHERE condition;
GROUP BY, ORDER BY, HAVING, COUNT(*), SUM(), AVG()
COMMIT : valide / ROLLBACK : annule
ON DELETE CASCADE : suppression en cascade.
